// Alphabet GSM 03.38 : remplace ce qui ferait passer le SMS à 70 caractères.
function versGsm(t) {
  const r = { 'ê': 'e', 'ë': 'e', 'â': 'a', 'î': 'i', 'ï': 'i', 'ô': 'o', 'û': 'u', 'ç': 'c', 'À': 'A', 'Â': 'A', 'È': 'E', 'Ê': 'E', 'Î': 'I',
    'Ô': 'O', 'Û': 'U', 'œ': 'oe', 'Œ': 'OE', '«': '"', '»': '"', '’': "'", '‘': "'", '“': '"', '”': '"', '–': '-', '—': '-', '…': '...', ' ': ' ', ' ': ' ' };
  return String(t).replace(/[^\n -~£¥èéùìòÇØøÅåÆæßÉÄÖÑÜ§¿äöñüà¡]/g, (c) => (r[c] !== undefined ? r[c] : c.normalize('NFD').replace(/[\u0300-\u036f]/g, '')));
}

